import re

RULE = re.compile(r'^\s*-{10,}\s*$')
BANNER = re.compile(r'ROBOCOPY\s+::')
HDR = re.compile(r'^\s*(?P<key>Started|Source|Dest|Files|Options|Ended|Exc Files|Exc Dirs|Job)\s*:\s*(?P<value>.*?)\s*$')
SPEED = re.compile(r'^\s*Speed\s*:\s*(?P<num>[\d.,]+)\s+(?P<unit>\S+?)\.?\s*$')
ENDED = re.compile(r'^\s*Ended\s*:\s*(?P<value>.*?)\s*$')
DIRL = re.compile(r'^\t\s*(?:(?P<status>New Dir|\*EXTRA Dir)\s+)?(?P<count>-?\d+)\t(?P<path>.+?)\s*$')
FILEL = re.compile(r'^\t\s*(?P<status>\S.*?)\s*\t+\s*(?P<size>[\d.]+(?:\s[kmgt])?)\t(?P<name>.+?)\s*$')
ERR = re.compile(r'^(?P<time>\d{4}/\d\d/\d\d \d\d:\d\d:\d\d) ERROR (?P<code>\d+) \((?P<hex>0x[0-9A-Fa-f]+)\) (?P<action>.*?)\s*$')
SUMH = re.compile(r'^\s*Total\s+Copied\s+Skipped')
SUMR = re.compile(r'^\s*(?P<label>Dirs|Files|Bytes|Times)\s*:')

def parse(lines):
    skip = []
    hdr = {}; hdr_l = []
    dirs = []; dirs_l = []
    files = []; files_l = []
    errs = []; errs_l = []
    summ = []; summ_l = []
    tail = {}; tail_l = []
    cols = None
    cur = ''
    last_err = None
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        if RULE.match(ln) or BANNER.search(ln):
            skip.append(i); continue
        if SUMH.match(ln):
            cols = [(m.group(0), m.end()) for m in re.finditer(r'\S+', ln)]
            summ_l.append(i); last_err = None; continue
        m = SUMR.match(ln)
        if cols is not None and m:
            rec = {'': m.group('label')}
            start = ln.index(':') + 1
            for name, end in cols:
                rec[name] = ln[start:end].strip()
                start = end
            summ.append(rec); summ_l.append(i); continue
        m = SPEED.match(ln)
        if m:
            tail['Speed ' + m.group('unit')] = m.group('num'); tail_l.append(i); continue
        if cols is not None:
            m = ENDED.match(ln)
            if m:
                tail['Ended'] = m.group('value'); tail_l.append(i); continue
        m = HDR.match(ln)
        if m and cols is None and not dirs:
            hdr[m.group('key')] = m.group('value'); hdr_l.append(i); continue
        m = ERR.match(ln)
        if m:
            last_err = {'Time': m.group('time'), 'Error': m.group('code'), 'Code': m.group('hex'), 'Action': m.group('action'), 'Message': '', 'Retry': ''}
            errs.append(last_err); errs_l.append(i); continue
        m = DIRL.match(ln)
        if m:
            cur = m.group('path')
            dirs.append({'Status': m.group('status') or '', 'Files': m.group('count'), 'Path': cur})
            dirs_l.append(i); last_err = None; continue
        m = FILEL.match(ln)
        if m:
            files.append({'Directory': cur, 'Status': m.group('status'), 'Size': m.group('size'), 'Name': m.group('name')})
            files_l.append(i); last_err = None; continue
        if last_err is not None:
            s = ln.strip()
            if s.startswith('Waiting'):
                last_err['Retry'] = s
            else:
                last_err['Message'] = (last_err['Message'] + ' ' + s).strip()
            errs_l.append(i); continue
        if cols is None and not dirs and not files and ln.strip() and not ln.strip().strip('\t'):
            skip.append(i)
    blocks = []
    if hdr: blocks.append({'name': 'job', 'kind': 'kv', 'lines': hdr_l, 'records': [hdr]})
    if dirs: blocks.append({'name': 'directories', 'kind': 'table', 'lines': dirs_l, 'records': dirs})
    if files: blocks.append({'name': 'files', 'kind': 'table', 'lines': files_l, 'records': files})
    if errs: blocks.append({'name': 'errors', 'kind': 'table', 'lines': errs_l, 'records': errs})
    if summ_l: blocks.append({'name': 'summary', 'kind': 'table', 'lines': summ_l, 'records': summ})
    if tail: blocks.append({'name': 'totals', 'kind': 'kv', 'lines': tail_l, 'records': [tail]})
    return {'blocks': blocks, 'skip': skip}
